// ---- src/03-chat.js ----
// #region sessions
// The playground chat pane is an ordinary DSH session: it is created in the
// chosen workspace, renamed, seeded with a teaching-instructions message, and then read
// through the Gateway Remote API (`remote.session.follow` + `observeState`).
// Sending a message is a normal `remote.session.prompt`, so the session stays
// visible in the sidebar, replayable and forkable like any other conversation.

/** Captured Client root context; chat code resolves services through it. */
let nestClientContext = null;

/** Prefix of the seeded instruction message; the pane folds it into a setup row. */
const NEST_SETUP_MARK = '〔NEST·设定〕';

/** Initial page budget for the opening snapshot of the chat session. */

/** Store key for managed-session ids; bump the suffix whenever the seeded instructions change. */
const NEST_SESSION_STORE = 'sessions.v2';
const NEST_FOLLOW_WINDOW = { maxMessages: 140, turnWindow: { minMessages: 90, minTurns: 8 } };

/** Map of `workspaceId:coach` -> in-flight ensure promise. */
const nestSessionJobs = new Map();

/** Read a persisted managed-session id for one workspace. */
function nestReadSessionId(workspaceId) {
	const store = nestReadStore(NEST_SESSION_STORE, null);
	if (store === null || typeof store !== 'object') return null;
	const value = store[workspaceId];
	return typeof value === 'string' && value !== '' ? value : null;
}

/** Persist a managed-session id for one workspace. */
function nestWriteSessionId(workspaceId, sessionId) {
	const store = nestReadStore(NEST_SESSION_STORE, null);
	const next = store !== null && typeof store === 'object' ? Object.assign({}, store) : {};
	next[workspaceId] = sessionId;
	nestWriteStore(NEST_SESSION_STORE, next);
}

/** Forget the managed-session id for one workspace (used by "new round"). */
function nestForgetSessionId(workspaceId) {
	const store = nestReadStore(NEST_SESSION_STORE, null);
	if (store === null || typeof store !== 'object') return;
	const next = Object.assign({}, store);
	delete next[workspaceId];
	nestWriteStore(NEST_SESSION_STORE, next);
	nestSessionJobs.delete(workspaceId + ':coach');
}

/** Resolve one RemoteResult and throw a readable error on failure. */
function nestUnwrapRemote(result, action) {
	if (result !== null && result !== undefined && result.ok === true) return result.value;
	const error = result !== null && result !== undefined ? result.error : undefined;
	const code = error !== null && error !== undefined && typeof error.code === 'string' ? error.code : '';
	const message = error !== null && error !== undefined && typeof error.message === 'string' ? error.message : 'unknown error';
	throw new Error(action + ': ' + (code !== '' ? code + ': ' : '') + message);
}

/** Compose the seeded teaching-instructions prompt (stable prefix for folding). */
function nestPersonaPrompt(t) {
	return NEST_SETUP_MARK + '\n' + t('chat.persona');
}

/**
 * Ensure the coach session exists for `workspaceId`. Reuses the persisted id
 * when the session still exists; otherwise creates, renames and seeds it.
 * Concurrent callers share one in-flight job.
 */
function nestEnsureSession(workspaceId, t) {
	const jobKey = workspaceId + ':coach';
	const inFlight = nestSessionJobs.get(jobKey);
	if (inFlight !== undefined) return inFlight;
	const job = (async () => {
		const stored = nestReadSessionId(workspaceId);
		if (stored !== null) {
			try {
				const state = await nestClientContext.remote.session.state({ sessionId: stored });
				if (state !== null && state !== undefined && state.ok === true) return stored;
			} catch (_error) {
				/* treat a failed check as a missing session */
			}
			nestForgetSessionId(workspaceId);
		}
		const created = await nestClientContext.remote.session.create({ workspaceId });
		const value = nestUnwrapRemote(created, 'create session');
		const sessionId = value.sessionId;
		nestWriteSessionId(workspaceId, sessionId);
		try {
			await nestClientContext.remote.session.rename({ sessionId, title: t('chat.title') + ' · ' + t('pg.title') });
		} catch (_error) {
			/* the title is cosmetic */
		}
		try {
			await nestSendPrompt(sessionId, nestPersonaPrompt(t));
		} catch (_error) {
			/* seeding is best-effort; the pane stays usable */
		}
		return sessionId;
	})();
	nestSessionJobs.set(jobKey, job);
	job.then(function () {}, function () {
		nestSessionJobs.delete(jobKey);
	});
	return job;
}

/** Send one text prompt into a session (queue mode, like the composer). */
async function nestSendPrompt(sessionId, text) {
	const request = {
		requestId: nestRequestId(),
		sessionId,
		mode: 'queue',
		content: [{ type: 'text', text }]
	};
	const zone = nestClientTimeZone();
	if (zone !== undefined) request.clientTimeZone = zone;
	const result = await nestClientContext.remote.session.prompt(request);
	nestUnwrapRemote(result, 'send prompt');
	return true;
}

/** Close one Remote stream handle, tolerating sync throws and async rejection. */
function nestDisposeStream(handle) {
	if (handle === null || handle === undefined) return;
	try {
		if (typeof handle.dispose !== 'function') return;
		const result = handle.dispose();
		if (result !== null && result !== undefined && typeof result.catch === 'function') result.catch(function () {});
	} catch (_error) {
		/* the carrier already closed */
	}
}

/** Open one managed session in the ordinary conversation view. */
function nestOpenSession(sessionId) {
	if (sessionId === null) return;
	try {
		nestClientContext.uiWorkspace.openSession(sessionId);
	} catch (_error) {
		/* navigation is best-effort */
	}
}
// #endregion

// #region chat folding
/** Add one live-chunk / surface envelope to an entry list without losing order. */
function nestAppendEntry(entries, entry) {
	const event = entry !== null && entry !== undefined ? entry.event : null;
	if (event === null || event === undefined) return entries;
	if (entry.type === 'transient') {
		// Live chunks are keyed by attempt + index; a replayed chunk must not be
		// appended twice (that would duplicate streamed assistant text).
		const data = event.data !== null && typeof event.data === 'object' ? event.data : null;
		const attemptId = data !== null && typeof data.attemptId === 'string' ? data.attemptId : '';
		if (attemptId !== '' && typeof event.seq === 'number') {
			for (let index = entries.length - 1; index >= 0; index -= 1) {
				const candidate = entries[index];
				if (candidate === null || candidate === undefined || candidate.type !== 'transient') continue;
				const candidateData = candidate.event !== null && candidate.event !== undefined && candidate.event.data !== null && typeof candidate.event.data === 'object' ? candidate.event.data : null;
				if (candidateData === null || candidate.event.type !== 'assistant/live-chunk') continue;
				if (candidateData.attemptId === attemptId && candidate.event.seq === event.seq) return entries;
			}
		}
		return entries.concat([entry]);
	}
	const last = entries.length > 0 ? entries[entries.length - 1] : null;
	const lastEvent = last !== null && last !== undefined ? last.event : null;
	const lastSeq = lastEvent !== null && lastEvent !== undefined && typeof lastEvent.seq === 'number' ? lastEvent.seq : -Infinity;
	const seq = typeof event.seq === 'number' ? event.seq : lastSeq + 1;
	// A durable event that is delivered twice (snapshot boundary + replayed
	// stream) must not produce two transcript rows.
	if (typeof event.seq === 'number') {
		for (const candidate of entries) {
			if (candidate !== null && candidate !== undefined && candidate.event !== null && candidate.event !== undefined && candidate.event.seq === event.seq) return entries;
		}
	}
	if (seq >= lastSeq) return entries.concat([entry]);
	const next = entries.slice();
	let index = next.length;
	while (index > 0) {
		const candidate = next[index - 1];
		const candidateSeq = candidate !== null && candidate !== undefined && candidate.event !== undefined && typeof candidate.event.seq === 'number' ? candidate.event.seq : -Infinity;
		if (candidateSeq <= seq) break;
		index -= 1;
	}
	next.splice(index, 0, entry);
	return next;
}

/** True when a surface event is an append (transcript must ignore replacements). */
function nestIsSurfaceAppend(event) {
	const op = event.surfaceOp;
	if (op === undefined || op === null) return true;
	return op === 'append';
}

/** Localizable turn failure descriptor from a `turn/end` reason. */
function nestTurnFailure(reason) {
	if (reason === null || typeof reason !== 'object') return null;
	if (reason.kind === 'error' && reason.error !== null && typeof reason.error === 'object') {
		return {
			message: typeof reason.error.message === 'string' ? reason.error.message : '',
			code: typeof reason.error.code === 'string' ? reason.error.code : ''
		};
	}
	if (reason.kind === 'aborted' && reason.reason !== null && typeof reason.reason === 'object'
		&& reason.reason.kind === 'hook' && reason.reason.reason === 'deepseek-account/signed-out') {
		return { message: '', code: 'ACCOUNT_SIGNED_OUT' };
	}
	if (reason.kind === 'interrupted') return { message: '', code: 'INTERRUPTED' };
	return null;
}

/** Append one text delta to a live assistant draft. */
function nestApplyTextChunk(draft, chunk) {
	if (chunk === null || typeof chunk !== 'object') return;
	if (chunk.type === 'text-delta' && typeof chunk.text === 'string') {
		draft.text += chunk.text;
	} else if (chunk.type === 'block-end' && chunk.block !== null && chunk.block !== undefined
		&& chunk.block.type === 'text' && typeof chunk.block.text === 'string' && draft.text === '') {
		draft.text = chunk.block.text;
	}
}

/**
 * Fold session entries into transcript rows.
 * Rows: {kind:'user'|'setup'|'assistant'|'tool'|'error'|'notice', ...}
 */
function nestFoldEntries(entries) {
	const rows = [];
	const drafts = new Map();
	const calls = new Map();
	const seenSeq = new Set();
	const assistantIds = new Set();
	const durableAssistantTexts = [];
	if (!Array.isArray(entries)) return rows;
	for (const entry of entries) {
		if (entry === null || entry === undefined) continue;
		const event = entry.event;
		if (event === null || event === undefined) continue;
		const data = event.data !== null && typeof event.data === 'object' ? event.data : {};
		const type = event.type;
		if (entry.type !== 'transient' && typeof event.seq === 'number') {
			if (seenSeq.has(event.seq)) continue;
			seenSeq.add(event.seq);
		}
		if (type === 'assistant/live-chunk') {
			const attemptId = typeof data.attemptId === 'string' ? data.attemptId : '';
			if (attemptId === '') continue;
			let draft = drafts.get(attemptId);
			if (draft === undefined) {
				draft = { attemptId, turn: -1, step: -1, text: '', time: event.time };
				drafts.set(attemptId, draft);
			}
			if (typeof data.turn === 'number') draft.turn = data.turn;
			if (typeof data.step === 'number') draft.step = data.step;
			nestApplyTextChunk(draft, data.chunk);
			continue;
		}
		if (entry.type === 'transient') continue;
		switch (type) {
			case 'user/message': {
				if (!nestIsSurfaceAppend(event)) break;
				const source = data.source !== null && typeof data.source === 'object' ? data.source : null;
				if (source === null || source.kind !== 'user') break;
				const text = nestTextOf(data.content);
				if (text === '') break;
				const isSetup = text.indexOf(NEST_SETUP_MARK) === 0;
				rows.push({
					kind: isSetup ? 'setup' : 'user',
					key: 'u' + String(event.seq),
					text,
					time: event.time,
					messageId: data.id
				});
				break;
			}
			case 'assistant/message': {
				if (!nestIsSurfaceAppend(event)) break;
				const turn = typeof data.turn === 'number' ? data.turn : -1;
				const step = typeof data.step === 'number' ? data.step : -1;
				const message = data.message !== null && typeof data.message === 'object' ? data.message : data;
				const text = nestTextOf(message !== null && message !== undefined ? message.content : undefined);
				/* The final message supersedes its streaming draft. Match by turn/step
				   and, as a safety net, by content when the chunk metadata was lost
				   (e.g. the stream was joined mid-turn and turn/step stayed -1). */
				for (const [attemptId, draft] of Array.from(drafts.entries())) {
					if (draft.turn === turn && draft.step === step) {
						drafts.delete(attemptId);
						continue;
					}
					const draftText = String(draft.text === undefined ? '' : draft.text).trim();
					if (text !== '' && draftText !== '' && draftText.length >= 8 && text.indexOf(draftText) === 0) drafts.delete(attemptId);
				}
				if (text !== '') {
					const messageId = message !== null && message !== undefined && typeof message.id === 'string' ? message.id : null;
					const duplicate = messageId !== null ? assistantIds.has(messageId) : rows.some((row) => row.kind === 'assistant' && row.text === text);
					if (messageId !== null) assistantIds.add(messageId);
					if (duplicate) break;
					durableAssistantTexts.push(text.trim());
					rows.push({
						kind: 'assistant',
						key: 'a' + String(event.seq),
						text,
						time: event.time,
						messageId: message !== null && message !== undefined ? message.id : undefined
					});
				}
				if (data.interrupted === true) {
					rows.push({ kind: 'notice', key: 'ni' + String(event.seq), notice: 'interrupted', time: event.time });
				}
				break;
			}
			case 'tool/call': {
				const callId = typeof data.callId === 'string' ? data.callId : '';
				const name = typeof data.name === 'string' ? data.name : 'tool';
				const args = typeof data.arguments === 'string' ? data.arguments : '';
				rows.push({ kind: 'tool', key: 't' + String(event.seq), callId, name, args, result: null, isError: false, time: event.time });
				if (callId !== '') calls.set(callId, rows.length - 1);
				break;
			}
			case 'tool/result': {
				if (!nestIsSurfaceAppend(event)) break;
				const message = data.message !== null && typeof data.message === 'object' ? data.message : {};
				const source = message.source !== null && typeof message.source === 'object' ? message.source : null;
				const callId = source !== null && typeof source.callId === 'string' ? source.callId : '';
				const resultText = nestTextOf(message.content);
				const isError = message.isError === true || (data.error !== undefined && data.error !== null);
				const rowIndex = callId !== '' ? calls.get(callId) : undefined;
				if (rowIndex !== undefined && rows[rowIndex] !== undefined) {
					rows[rowIndex] = Object.assign({}, rows[rowIndex], { result: resultText, isError, resultTime: event.time });
				} else {
					rows.push({
						kind: 'tool',
						key: 'tr' + String(event.seq),
						callId,
						name: typeof data.name === 'string' ? data.name : 'tool',
						args: '',
						result: resultText,
						isError,
						time: event.time
					});
				}
				break;
			}
			case 'turn/end': {
				const reason = data.reason !== null && typeof data.reason === 'object' ? data.reason : {};
				const failure = nestTurnFailure(reason);
				if (failure !== null) {
					rows.push({ kind: 'error', key: 'e' + String(event.seq), detail: failure.message, code: failure.code, time: event.time });
				}
				if (reason.kind === 'max-tokens') {
					rows.push({ kind: 'notice', key: 'nm' + String(event.seq), notice: 'maxTokens', time: event.time });
				}
				drafts.clear();
				break;
			}
			case 'compaction/summary': {
				rows.push({ kind: 'notice', key: 'nc' + String(event.seq), notice: 'compacted', time: event.time });
				break;
			}
			default:
				break;
		}
	}
	const live = Array.from(drafts.values()).filter((draft) => draft.text !== '');
	live.sort((left, right) => (left.turn - right.turn) || (left.step - right.step));
	const renderedLive = new Set();
	for (const draft of live) {
		const draftText = String(draft.text === undefined ? '' : draft.text).trim();
		if (draftText === '' || renderedLive.has(draftText)) continue;
		const covered = durableAssistantTexts.some((durableText) => durableText === draftText
			|| (draftText.length >= 12 && durableText.length > draftText.length && durableText.indexOf(draftText) === 0));
		if (covered) continue;
		renderedLive.add(draftText);
		rows.push({ kind: 'assistant', key: 'live-' + draft.attemptId, text: draft.text, time: draft.time, streaming: true });
	}
	return rows;
}
// #endregion

// #region chat hooks
/**
 * Live transcript for the coach session: opening snapshot from `follow`,
 * durable appends, streaming assistant chunks, and running state.
 */
function nestUseSessionChat(sessionId) {
	const [entries, setEntries] = React.useState(NEST_EMPTY);
	const [phase, setPhase] = React.useState(sessionId === null ? 'idle' : 'loading');
	const [error, setError] = React.useState(null);
	const [running, setRunning] = React.useState(false);
	const [reloadToken, setReloadToken] = React.useState(0);
	const attemptsRef = React.useRef(new Map());

	React.useEffect(() => {
		if (sessionId === null) {
			setEntries(NEST_EMPTY);
			setPhase('idle');
			setRunning(false);
			return undefined;
		}
		let alive = true;
		let follow = null;
		const controller = new AbortController();
		const attempts = new Map();
		attemptsRef.current = attempts;
		setEntries(NEST_EMPTY);
		setError(null);
		setRunning(false);
		setPhase('loading');
		try {
			follow = nestClientContext.remote.session.follow({
				address: { kind: 'session', sessionId },
				activate: true,
				assistantStream: true,
				maxMessages: NEST_FOLLOW_WINDOW.maxMessages,
				turnWindow: NEST_FOLLOW_WINDOW.turnWindow
			}, controller.signal);
		} catch (caught) {
			setPhase('error');
			setError(nestErrorMessage(caught));
			return undefined;
		}
		(async () => {
			try {
				for await (const frame of follow) {
					if (!alive) return;
					if (frame === null || typeof frame !== 'object') continue;
					if (frame.type === 'snapshot') {
						setEntries(Array.isArray(frame.records) ? frame.records : NEST_EMPTY);
						setPhase('ready');
						const baseline = frame.assistantStream;
						const active = baseline !== null && baseline !== undefined ? baseline.activeAttempt : null;
						if (active !== null && active !== undefined && typeof active.attemptId === 'string') {
							attempts.set(active.attemptId, { turn: active.turn, step: active.step });
						}
						continue;
					}
					if (frame.type === 'event') {
						setEntries((previous) => nestAppendEntry(previous, { type: 'event', event: frame.event }));
						setPhase('ready');
						continue;
					}
					if (frame.type === 'assistant-stream') {
						const streamFrame = frame.frame;
						if (streamFrame === null || streamFrame === undefined) continue;
						if (streamFrame.type === 'start' && typeof streamFrame.attemptId === 'string') {
							attempts.set(streamFrame.attemptId, { turn: streamFrame.turn, step: streamFrame.step });
							continue;
						}
						if (streamFrame.type === 'chunk' && typeof streamFrame.attemptId === 'string') {
							const meta = attempts.get(streamFrame.attemptId) || { turn: -1, step: -1 };
							const index = typeof streamFrame.index === 'number' ? streamFrame.index : 0;
							setEntries((previous) => nestAppendEntry(previous, {
								type: 'transient',
								event: {
									type: 'assistant/live-chunk',
									seq: index,
									time: streamFrame.time,
									data: {
										attemptId: streamFrame.attemptId,
										turn: meta.turn,
										step: meta.step,
										chunk: streamFrame.chunk
									}
								}
							}));
						}
					}
				}
			} catch (caught) {
				if (!alive || controller.signal.aborted) return;
				setPhase('error');
				setError(nestErrorMessage(caught));
			}
		})();
		return () => {
			alive = false;
			controller.abort();
			nestDisposeStream(follow);
		};
	}, [sessionId, reloadToken]);

	React.useEffect(() => {
		if (sessionId === null) return undefined;
		let alive = true;
		let handle = null;
		const controller = new AbortController();
		try {
			handle = nestClientContext.remote.session.observeState({ sessionId }, controller.signal);
		} catch (_error) {
			return undefined;
		}
		(async () => {
			try {
				for await (const state of handle) {
					if (!alive) return;
					if (state !== null && typeof state === 'object') setRunning(state.running === true);
				}
			} catch (_error) {
				/* state is an enhancement; ignore carrier failures */
			}
		})();
		return () => {
			alive = false;
			controller.abort();
			nestDisposeStream(handle);
		};
	}, [sessionId]);

	const rows = React.useMemo(() => nestFoldEntries(entries), [entries]);
	const reload = React.useCallback(() => setReloadToken((value) => value + 1), []);
	return { rows, phase, error, running, reload };
}

/**
 * The coach session for one workspace. Creates/seeds it lazily — only while
 * `active` (the playground tab is open) — so merely opening the panel never
 * starts a model turn. Exposes `newRound` for "start over".
 */
function nestUsePaneSession(workspaceId, t, active) {
	const [sessionId, setSessionId] = React.useState(null);
	const [phase, setPhase] = React.useState(() => {
		if (workspaceId === null) return 'waiting';
		return active === true ? 'creating' : 'idle';
	});
	const [error, setError] = React.useState(null);
	const [generation, setGeneration] = React.useState(0);

	React.useEffect(() => {
		if (workspaceId === null || active !== true) {
			setSessionId(null);
			setPhase(workspaceId === null ? 'waiting' : 'idle');
			setError(null);
			return undefined;
		}
		let alive = true;
		setPhase('creating');
		setError(null);
		nestEnsureSession(workspaceId, t).then((id) => {
			if (!alive) return;
			setSessionId(id);
			setPhase('ready');
		}, (caught) => {
			if (!alive) return;
			setSessionId(null);
			setPhase('error');
			setError(nestErrorMessage(caught));
		});
		return () => {
			alive = false;
		};
	}, [workspaceId, generation, active]);

	const newRound = React.useCallback(() => {
		if (workspaceId === null) return;
		nestForgetSessionId(workspaceId);
		setSessionId(null);
		setPhase('creating');
		setGeneration((value) => value + 1);
	}, [workspaceId]);

	return { sessionId, phase, error, newRound };
}
// #endregion

// #region chat pane
/** Localized text for one turn-failure code. */
function nestFailureText(t, row) {
	if (row.code === 'ACCOUNT_SIGNED_OUT') return t('chat.accountSignedOut');
	if (row.code === 'INTERRUPTED') return t('chat.turnInterrupted');
	const detail = typeof row.detail === 'string' ? row.detail : '';
	return detail !== '' ? detail : t('chat.turnFailed');
}

/** One transcript row of the coach pane. */
function NestChatRow(props) {
	const row = props.row;
	const t = props.t;
	if (row === null || row === undefined) return null;
	if (row.kind === 'setup') {
		return h('details', { className: 'ne-setupRow', key: row.key },
			h('summary', { className: 'ne-setupSummary' }, NestGlyph({ name: 'info', size: 13 }), h('span', null, t('chat.setupLabel'))),
			h('p', { className: 'ne-setupText' }, row.text)
		);
	}
	if (row.kind === 'user') {
		return h('article', { className: 'ne-msg ne-msgUser', key: row.key },
			h('div', { className: 'ne-msgMeta' },
				h('span', { className: 'ne-msgWho' }, t('chat.you')),
				row.time !== undefined ? h('time', { className: 'ne-msgTime' }, nestTimeLabel(row.time)) : null
			),
			h('div', { className: 'ne-bubble ne-bubbleUser' }, nestRenderRichText(row.text))
		);
	}
	if (row.kind === 'assistant') {
		return h('article', { className: 'ne-msg ne-msgAi', key: row.key },
			h('div', { className: 'ne-msgMeta' },
				h('span', { className: 'ne-aiBadge' }, NestPanelIcon({ size: 13 })),
				h('span', { className: 'ne-msgWho' }, t('chat.title')),
				row.time !== undefined ? h('time', { className: 'ne-msgTime' }, nestTimeLabel(row.time)) : null
			),
			h('div', { className: 'ne-bubble ne-bubbleAi' },
				nestRenderRichText(row.text),
				row.streaming === true ? h('span', { className: 'ne-caret', 'aria-hidden': true }) : null
			)
		);
	}
	if (row.kind === 'tool') {
		const failed = row.isError === true;
		const summary = h('summary', { className: 'ne-toolSummary' },
			NestGlyph({ name: 'terminal', size: 13 }),
			h('span', null, t('chat.toolCall')),
			h('code', { className: 'ne-toolName' }, row.name),
			failed ? h('span', { className: 'ne-toolState' }, t('chat.toolFailed')) : null
		);
		const body = [];
		if (typeof row.args === 'string' && row.args !== '') {
			body.push(h('pre', { className: 'ne-toolPre', key: 'args' }, nestClipText(row.args, 1200)));
		}
		if (typeof row.result === 'string' && row.result !== '') {
			body.push(h('pre', { className: 'ne-toolPre', key: 'result' }, nestClipText(row.result, 1600)));
		}
		return h('details', { className: 'ne-toolRow', key: row.key, 'data-error': failed ? 'true' : undefined }, summary, body.length > 0 ? body : null);
	}
	if (row.kind === 'error') {
		return h('div', { className: 'ne-rowError', key: row.key, role: 'status' },
			NestGlyph({ name: 'alert', size: 13 }),
			h('span', null, t('chat.turnFailed') + ' · ' + nestFailureText(t, row))
		);
	}
	if (row.kind === 'notice') {
		let text = '';
		if (row.notice === 'maxTokens') text = t('chat.maxTokens');
		else if (row.notice === 'compacted') text = t('chat.compacted');
		else if (row.notice === 'interrupted') text = t('chat.turnInterrupted');
		if (text === '') return null;
		return h('div', { className: 'ne-rowNotice', key: row.key }, NestGlyph({ name: 'info', size: 12 }), h('span', null, text));
	}
	return null;
}

/**
 * The coach pane: header, transcript and composer. `pendingPrompt` carries a
 * queued prompt from another tab ({ id, text }); the pane sends it once the
 * session is ready and calls `onPromptSent(id)`.
 */
function NestChatPane(props) {
	const t = props.t;
	const pane = props.pane;
	const pendingPrompt = props.pendingPrompt;
	const onPromptSent = props.onPromptSent;
	const chat = nestUseSessionChat(pane.sessionId);
	const [draft, setDraft] = React.useState('');
	const [sending, setSending] = React.useState(false);
	const [notice, setNotice] = React.useState(null);
	const listRef = React.useRef(null);
	const stickRef = React.useRef(true);
	const sentRef = React.useRef(new Set());

	React.useEffect(() => {
		if (!stickRef.current) return;
		const node = listRef.current;
		if (node !== null) node.scrollTop = node.scrollHeight;
	}, [chat.rows, chat.running]);

	React.useEffect(() => {
		if (pendingPrompt === null || pendingPrompt === undefined) return;
		if (sentRef.current.has(pendingPrompt.id)) return;
		if (pane.phase !== 'ready' || pane.sessionId === null) return;
		sentRef.current.add(pendingPrompt.id);
		(async () => {
			try {
				await nestSendPrompt(pane.sessionId, pendingPrompt.text);
			} catch (error) {
				setNotice({ tone: 'error', text: t('chat.sendFailed') + nestErrorMessage(error) });
			} finally {
				if (typeof onPromptSent === 'function') onPromptSent(pendingPrompt.id);
			}
		})();
	}, [pendingPrompt, pane.phase, pane.sessionId]);

	const onScroll = () => {
		const node = listRef.current;
		if (node === null) return;
		stickRef.current = node.scrollHeight - node.scrollTop - node.clientHeight < 90;
	};

	const ready = pane.phase === 'ready' && pane.sessionId !== null;
	const canSend = ready && !sending;

	const send = async () => {
		const text = draft.trim();
		if (text === '' || !canSend) return;
		setDraft('');
		setSending(true);
		setNotice(null);
		try {
			await nestSendPrompt(pane.sessionId, text);
		} catch (error) {
			setDraft(text);
			setNotice({ tone: 'error', text: t('chat.sendFailed') + nestErrorMessage(error) });
		} finally {
			setSending(false);
		}
	};

	const onKeyDown = (event) => {
		if (event.key !== 'Enter' || event.shiftKey) return;
		const native = event.nativeEvent;
		if (native !== null && native !== undefined && (native.isComposing === true || native.keyCode === 229)) return;
		event.preventDefault();
		send();
	};

	const hasStreaming = chat.rows.some((row) => row.kind === 'assistant' && row.streaming === true);
	let body = null;
	if (pane.phase === 'creating') {
		body = h('div', { className: 'ne-paneState' }, NestSpinner({}), h('span', null, t('chat.creating')));
	} else if (pane.phase === 'error') {
		body = h('div', { className: 'ne-paneState ne-paneStateError' },
			h('p', null, t('chat.sessionError') + (pane.error === null ? '' : pane.error)),
			h('button', { className: 'ne-btn ne-btnGhost', type: 'button', onClick: pane.newRound }, t('chat.retry'))
		);
	} else if (pane.phase === 'waiting') {
		body = h('div', { className: 'ne-paneState' },
			NestGlyph({ name: 'compass', size: 22 }),
			h('p', null, t('workspace.empty')),
			h('p', { className: 'ne-muted' }, t('workspace.emptyHint'))
		);
	} else if (chat.phase === 'loading' && chat.rows.length === 0) {
		body = h('div', { className: 'ne-paneState' }, NestSpinner({}), h('span', null, t('chat.loading')));
	} else {
		const rows = chat.rows.map((row) => h(NestChatRow, { key: row.key, row, t }));
		const empty = chat.rows.length === 0 && chat.phase === 'ready';
		body = h('div', { className: 'ne-paneBody' },
			chat.error !== null
				? h('div', { className: 'ne-paneBanner' },
					h('span', null, t('chat.errorPrefix') + chat.error),
					h('button', { className: 'ne-btn ne-btnGhost ne-btnSmall', type: 'button', onClick: chat.reload }, t('chat.retry')))
				: null,
			empty
				? h('div', { className: 'ne-paneEmpty' }, NestPanelIcon({ size: 24 }), h('p', null, t('chat.empty')))
				: null,
			h('div', { className: 'ne-transcript', ref: listRef, onScroll, role: 'log', 'aria-live': 'polite' },
				rows,
				chat.running && chat.phase === 'ready' && !hasStreaming
					? h('div', { className: 'ne-typing' },
						h('span', { className: 'ne-typingDots' }, h('i', null), h('i', null), h('i', null)),
						h('span', { className: 'ne-typingText' }, t('chat.typing')))
					: null
			)
		);
	}

	return h('section', { className: 'ne-chatPane', 'aria-label': t('chat.title') },
		h('header', { className: 'ne-chatPaneHead' },
			h('div', { className: 'ne-chatIdentity' },
				h('span', { className: 'ne-chatDot', 'data-state': chat.running ? 'running' : 'idle' }),
				h('div', { className: 'ne-chatText' },
					h('h3', { className: 'ne-chatTitle' }, t('chat.title')),
					h('p', { className: 'ne-chatDesc' }, t('chat.desc'))
				)
			),
			h('div', { className: 'ne-chatActions' },
				pane.sessionId !== null
					? h('button', {
						className: 'ne-iconBtn',
						type: 'button',
						title: t('chat.openConversation'),
						'aria-label': t('chat.openConversation'),
						onClick: () => nestOpenSession(pane.sessionId)
					}, NestGlyph({ name: 'external', size: 15 }))
					: null,
				h('button', {
					className: 'ne-iconBtn',
					type: 'button',
					title: t('chat.newRound'),
					'aria-label': t('chat.newRound'),
					disabled: pane.phase === 'creating',
					onClick: pane.newRound
				}, NestGlyph({ name: 'refresh', size: 15 }))
			)
		),
		body,
		h('footer', { className: 'ne-composer' },
			notice !== null ? h('p', { className: 'ne-composerNotice', 'data-tone': notice.tone }, notice.text) : null,
			h('div', { className: 'ne-composerRow' },
				h('textarea', {
					className: 'ne-composerInput',
					rows: Math.min(5, Math.max(1, draft.split('\n').length)),
					value: draft,
					placeholder: t('chat.placeholder'),
					'aria-label': t('chat.placeholder'),
					disabled: !ready,
					onChange: (event) => setDraft(event.target.value),
					onKeyDown
				}),
				h('button', {
					className: 'ne-sendBtn',
					type: 'button',
					disabled: !canSend || draft.trim() === '',
					title: t('chat.send'),
					'aria-label': t('chat.send'),
					onClick: send
				}, sending ? NestSpinner({ onBrand: true }) : NestGlyph({ name: 'send' }))
			),
			h('p', { className: 'ne-composerHint' }, t('chat.hint'))
		)
	);
}
// #endregion

// ---- src/04-styles-base.js ----
// #region base styles
// Shared chrome for the NestJS Assistant panel: page layout, header, tabs,
// buttons, chips, transcript rows and the coach composer. View-specific styles
// live in src/styles/*.js and only add their own prefixed rules.
// Only host theme tokens are used as colors; literal colors never appear here.

const NEST_CSS_BASE = `
.ne-page {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--dsw-alias-bg-base);
  color: var(--dsw-alias-label-primary);
  font-size: 13px;
  line-height: 1.55;
  overflow: hidden;
}
.ne-page *, .ne-page *::before, .ne-page *::after { box-sizing: border-box; }
:where(.ne-page) button, :where(.ne-page) input, :where(.ne-page) textarea, :where(.ne-page) select {
  font-family: inherit; color: inherit;
}
.ne-page code, .ne-page pre { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }

.ne-header {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 64px;
  padding: 11px 22px 10px;
  flex: none;
  background:
    radial-gradient(ellipse at 4% 0%, color-mix(in srgb, var(--dsw-alias-brand-primary) 9%, transparent), transparent 42%),
    linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-bg-layer-1) 58%, transparent), transparent);
}
.ne-brand { display: flex; align-items: center; gap: 11px; min-width: 0; }
.ne-brandMark {
  width: 38px; height: 38px; flex: none;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 12px;
  color: var(--dsw-alias-brand-primary);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--dsw-alias-brand-primary) 18%, var(--dsw-alias-bg-layer-1)), var(--dsw-alias-bg-layer-1));
  border: 1px solid color-mix(in srgb, var(--dsw-alias-brand-primary) 26%, transparent);
  box-shadow: 0 4px 14px color-mix(in srgb, var(--dsw-alias-brand-primary) 10%, transparent);
}
.ne-brandText { min-width: 0; }
.ne-title { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: 0.1px; line-height: 1.35; }
.ne-subtitle { margin: 2px 0 0; font-size: 11px; color: var(--dsw-alias-label-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ne-headerEnd { margin-left: auto; display: flex; align-items: center; gap: 9px; flex: none; }
.ne-eyebrow { display: inline-block; margin-bottom: 6px; font-size: 9.5px; font-weight: 700; letter-spacing: 1.3px; color: var(--dsw-alias-brand-primary); opacity: 0.85; text-transform: uppercase; }

.ne-wsField { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.ne-wsSelect {
  max-width: 190px; min-height: 29px; padding: 5px 8px; border-radius: 8px; font-size: 12px;
  border: 1px solid var(--dsw-alias-border-l1);
  background: var(--dsw-alias-bg-layer-1); outline: none;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}
.ne-wsSelect:focus { border-color: color-mix(in srgb, var(--dsw-alias-brand-primary) 55%, var(--dsw-alias-border-l1)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-brand-primary) 9%, transparent); }
.ne-statChip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px; border-radius: 999px; font-size: 11px;
  color: var(--dsw-alias-label-secondary);
  border: 1px solid var(--dsw-alias-border-l1);
  background: color-mix(in srgb, var(--dsw-alias-bg-layer-1) 72%, transparent);
}
.ne-statChip .ne-glyph { color: var(--dsw-alias-brand-primary); }

.ne-tabs {
  display: flex; gap: 4px; padding: 0 20px;
  border-bottom: 1px solid var(--dsw-alias-border-l1); flex: none;
  background: color-mix(in srgb, var(--dsw-alias-bg-layer-1) 28%, transparent);
}
.ne-tab {
  position: relative;
  display: inline-flex; align-items: center; gap: 7px;
  padding: 9px 14px 10px; border: none; background: transparent; cursor: pointer;
  color: var(--dsw-alias-label-secondary); font-size: 12.5px;
  border-radius: 8px 8px 0 0;
  transition: color 140ms ease, background 140ms ease;
}
.ne-tab::after {
  content: ''; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px;
  border-radius: 2px 2px 0 0; background: transparent;
}
.ne-tab:hover { color: var(--dsw-alias-label-primary); background: color-mix(in srgb, var(--dsw-alias-label-primary) 4%, transparent); }
.ne-tab[aria-selected="true"] {
  color: var(--dsw-alias-brand-primary); font-weight: 650;
  background: color-mix(in srgb, var(--dsw-alias-brand-primary) 7%, transparent);
}
.ne-tab[aria-selected="true"]::after { background: var(--dsw-alias-brand-primary); }
.ne-tab:focus-visible, .ne-btn:focus-visible, .ne-iconBtn:focus-visible, .ne-linkBtn:focus-visible {
  outline: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-brand-primary) 20%, transparent);
}

.ne-body { flex: 1; min-height: 0; display: flex; overflow: hidden; }
.ne-scroll { overflow-y: auto; overflow-x: hidden; scrollbar-gutter: stable; }
.ne-scroll::-webkit-scrollbar, .ne-transcript::-webkit-scrollbar, .ne-codeScroll::-webkit-scrollbar { width: 9px; height: 9px; }
.ne-scroll::-webkit-scrollbar-track, .ne-transcript::-webkit-scrollbar-track { background: transparent; }
.ne-scroll::-webkit-scrollbar-thumb, .ne-transcript::-webkit-scrollbar-thumb, .ne-codeScroll::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--dsw-alias-label-secondary) 24%, transparent);
  border-radius: 999px; border: 2px solid transparent; background-clip: content-box;
}
.ne-scroll::-webkit-scrollbar-thumb:hover, .ne-transcript::-webkit-scrollbar-thumb:hover { background: color-mix(in srgb, var(--dsw-alias-label-secondary) 40%, transparent); background-clip: content-box; }
.ne-muted { color: var(--dsw-alias-label-secondary); }
.ne-empty { padding: 34px 18px; text-align: center; color: var(--dsw-alias-label-secondary); display: flex; flex-direction: column; align-items: center; gap: 10px; }

.ne-input, .ne-select {
  min-height: 30px; padding: 6px 9px; border-radius: 8px; font-size: 12px;
  border: 1px solid var(--dsw-alias-border-l1);
  background: var(--dsw-alias-bg-base);
  color: var(--dsw-alias-label-primary); outline: none; min-width: 0;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}
.ne-input:hover, .ne-select:hover { border-color: var(--dsw-alias-border-l2); }
.ne-input:focus, .ne-select:focus {
  border-color: color-mix(in srgb, var(--dsw-alias-brand-primary) 55%, var(--dsw-alias-border-l1));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-brand-primary) 9%, transparent);
}
.ne-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 30px; padding: 5px 11px; border-radius: 8px; cursor: pointer;
  border: 1px solid var(--dsw-alias-border-l1);
  background: var(--dsw-alias-bg-layer-1);
  color: var(--dsw-alias-label-primary); font-size: 12px;
  transition: background 120ms ease, border-color 120ms ease, opacity 120ms ease, transform 120ms ease, box-shadow 120ms ease;
  white-space: nowrap;
}
.ne-btn:hover { background: var(--dsw-alias-bg-layer-2); border-color: var(--dsw-alias-border-l2); }
.ne-btn:active:not(:disabled) { transform: translateY(1px); }
.ne-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.ne-btnPrimary { background: var(--dsw-alias-brand-primary); border-color: transparent; color: var(--dsw-alias-bg-base); font-weight: 650; box-shadow: 0 2px 8px color-mix(in srgb, var(--dsw-alias-brand-primary) 18%, transparent); }
.ne-btnPrimary:hover { background: color-mix(in srgb, var(--dsw-alias-brand-primary) 86%, var(--dsw-alias-label-primary)); box-shadow: 0 3px 12px color-mix(in srgb, var(--dsw-alias-brand-primary) 24%, transparent); }
.ne-btnGhost { background: transparent; }
.ne-btnGhost:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); }
.ne-btnSmall { padding: 4px 8px; font-size: 11.5px; border-radius: 7px; }
.ne-btnDanger { color: var(--dsw-alias-state-error-primary); }
.ne-linkBtn { border: none; background: none; padding: 0; color: var(--dsw-alias-brand-primary); cursor: pointer; font-size: 12px; }
.ne-linkBtn:hover { text-decoration: underline; }
.ne-iconBtn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: 7px; cursor: pointer;
  border: 1px solid transparent; background: transparent; color: var(--dsw-alias-label-secondary);
  transition: background 120ms ease, color 120ms ease;
}
.ne-iconBtn:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 7%, transparent); color: var(--dsw-alias-label-primary); }
.ne-iconBtn:active { background: color-mix(in srgb, var(--dsw-alias-label-primary) 10%, transparent); }
.ne-iconBtn:disabled { opacity: 0.4; cursor: not-allowed; }

.ne-chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px; border-radius: 999px; font-size: 10.5px;
  border: 1px solid var(--dsw-alias-border-l1);
  color: var(--dsw-alias-label-secondary); background: var(--dsw-alias-bg-layer-1);
  white-space: nowrap; line-height: 1.6;
}
.ne-chipSoft { border-color: transparent; background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); }
.ne-chipBrand { color: var(--dsw-alias-brand-primary); border-color: color-mix(in srgb, var(--dsw-alias-brand-primary) 30%, transparent); background: color-mix(in srgb, var(--dsw-alias-brand-primary) 8%, transparent); }
.ne-pillRow { display: flex; flex-wrap: wrap; gap: 6px; }

.ne-sectionTitle { margin: 0; font-size: 13.5px; font-weight: 650; }
.ne-sectionHead { display: flex; align-items: flex-start; gap: 14px; padding: 16px 20px 12px; flex: none; }
.ne-sectionHeading { min-width: 0; }
.ne-sectionIntro { margin: 4px 0 0; color: var(--dsw-alias-label-secondary); font-size: 12px; max-width: 780px; }

.ne-spinner {
  width: 14px; height: 14px; flex: none; display: inline-block;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--dsw-alias-label-secondary) 30%, transparent);
  border-top-color: var(--dsw-alias-label-secondary);
  animation: ne-spin 0.8s linear infinite;
}
.ne-spinnerOnBrand { border-color: color-mix(in srgb, var(--dsw-alias-bg-base) 35%, transparent); border-top-color: var(--dsw-alias-bg-base); }
@keyframes ne-spin { to { transform: rotate(360deg); } }

.ne-statusPill { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.ne-statusDot { width: 7px; height: 7px; border-radius: 50%; background: var(--dsw-alias-state-idle-primary); flex: none; }
.ne-statusPill[data-tone="running"] .ne-statusDot { background: var(--dsw-alias-state-success-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-state-success-primary) 18%, transparent); animation: ne-pulse 1.6s ease-in-out infinite; }
.ne-statusPill[data-tone="error"] .ne-statusDot { background: var(--dsw-alias-state-error-primary); }
.ne-statusPill[data-tone="warn"] .ne-statusDot { background: var(--dsw-alias-state-warn-primary); }
@keyframes ne-pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.45; } }

.ne-toast {
  position: absolute; right: 20px; bottom: 18px; max-width: 460px;
  padding: 9px 13px; border-radius: 9px; font-size: 12px; z-index: 20;
  background: var(--dsw-alias-bg-overlay);
  border: 1px solid var(--dsw-alias-border-l2);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--dsw-alias-label-primary) 16%, transparent);
}
.ne-toast[data-tone="error"] { border-color: color-mix(in srgb, var(--dsw-alias-state-error-primary) 45%, transparent); color: var(--dsw-alias-state-error-primary); }

.ne-inlineCode {
  padding: 1px 5px; border-radius: 5px; font-size: 0.92em;
  background: color-mix(in srgb, var(--dsw-alias-label-primary) 8%, transparent);
}
.ne-inlineLink { color: var(--dsw-alias-brand-primary); text-decoration: none; }
.ne-inlineLink:hover { text-decoration: underline; }
.ne-richPara { margin: 0 0 9px; }
.ne-richHead { margin: 14px 0 7px; font-size: 13.5px; }
.ne-richList { margin: 0 0 10px; padding-left: 20px; }
.ne-richList li { margin: 2px 0; }
.ne-richQuote { margin: 0 0 10px; padding: 2px 12px; border-left: 2px solid var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); }
.ne-richCode {
  margin: 0 0 10px; padding: 10px 12px; border-radius: 8px; overflow-x: auto;
  background: var(--dsw-alias-bg-layer-2); border: 1px solid var(--dsw-alias-border-l1);
  font-size: 11.5px; line-height: 1.5;
}

/* ---- rendered markdown: One Dark code blocks, tables, rules ---- */
.ne-oneDark {
  --ne-od-bg: #282c34;
  --ne-od-bg-deep: #21252b;
  --ne-od-border: #181a1f;
  --ne-od-fg: #abb2bf;
  --ne-od-muted: #7f848e;
  --ne-od-comment: #5c6370;
  --ne-od-gutter: #4b5263;
  --ne-od-purple: #c678dd;
  --ne-od-green: #98c379;
  --ne-od-orange: #d19a66;
  --ne-od-yellow: #e5c07b;
  --ne-od-blue: #61afef;
  --ne-od-red: #e06c75;
  --ne-od-cyan: #56b6c2;
}
.ne-mdCode {
  margin: 0 0 10px; border: 1px solid var(--ne-od-border); border-radius: 9px; overflow: hidden;
  background: var(--ne-od-bg); color: var(--ne-od-fg);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11.5px; line-height: 1.6;
}
.ne-mdCodeHead {
  display: flex; align-items: center; gap: 8px; min-height: 24px; padding: 3px 10px;
  background: var(--ne-od-bg-deep); border-bottom: 1px solid var(--ne-od-border);
  color: var(--ne-od-muted); font-size: 10px; letter-spacing: 0.3px;
}
.ne-mdCodeDots { display: inline-flex; align-items: center; gap: 4px; flex: none; }
.ne-mdCodeDots i { width: 7px; height: 7px; border-radius: 50%; background: #4b5263; display: block; }
.ne-mdCodeDots i:first-child { background: #e06c75; }
.ne-mdCodeDots i:nth-child(2) { background: #e5c07b; }
.ne-mdCodeDots i:nth-child(3) { background: #98c379; }
.ne-mdCodeLang { margin-left: auto; color: var(--ne-od-green); font-weight: 700; text-transform: uppercase; font-size: 9.5px; }
.ne-mdCodePre { margin: 0; padding: 9px 12px; overflow-x: auto; white-space: pre; tab-size: 2; color: var(--ne-od-fg); }
.ne-mdTokLine { display: block; min-height: 1.6em; }
.ne-mdTokKw { color: var(--ne-od-purple); font-weight: 600; }
.ne-mdTokStr { color: var(--ne-od-green); }
.ne-mdTokCom { color: var(--ne-od-comment); font-style: italic; }
.ne-mdTokDec { color: var(--ne-od-yellow); }
.ne-mdTokNum { color: var(--ne-od-orange); }
.ne-mdTokFn { color: var(--ne-od-blue); }
.ne-mdTokType { color: var(--ne-od-yellow); }
.ne-inlineDel { color: var(--dsw-alias-label-secondary); text-decoration: line-through; }
.ne-mdHr { margin: 12px 0; border: none; border-top: 1px solid var(--dsw-alias-border-l2); }
.ne-mdTableWrap { margin: 0 0 10px; overflow-x: auto; border: 1px solid var(--dsw-alias-border-l1); border-radius: 8px; }
.ne-mdTable { border-collapse: collapse; width: 100%; font-size: 11.5px; }
.ne-mdTable th, .ne-mdTable td { padding: 5px 9px; border-bottom: 1px solid var(--dsw-alias-border-l1); text-align: left; vertical-align: top; }
.ne-mdTable th { background: color-mix(in srgb, var(--dsw-alias-label-primary) 4%, transparent); font-weight: 650; white-space: nowrap; color: var(--dsw-alias-label-primary); }
.ne-mdTable tr:last-child td { border-bottom: none; }

/* ---- coach chat pane (used inside the playground) ---- */
.ne-chatPane { display: flex; flex-direction: column; min-height: 0; min-width: 0; height: 100%; background: var(--dsw-alias-bg-base); }
.ne-chatPaneHead {
  display: flex; align-items: center; gap: 10px; flex: none;
  padding: 13px 14px 12px; border-bottom: 1px solid var(--dsw-alias-border-l1);
  background: color-mix(in srgb, var(--dsw-alias-brand-primary) 3%, var(--dsw-alias-bg-base));
}
.ne-chatIdentity { display: flex; align-items: center; gap: 9px; min-width: 0; }
.ne-chatDot { width: 8px; height: 8px; border-radius: 50%; background: var(--dsw-alias-state-idle-primary); flex: none; }
.ne-chatDot[data-state="running"] { background: var(--dsw-alias-state-success-primary); animation: ne-pulse 1.6s ease-in-out infinite; }
.ne-chatText { min-width: 0; }
.ne-chatTitle { margin: 0; font-size: 13px; font-weight: 650; }
.ne-chatDesc { margin: 0; font-size: 11px; color: var(--dsw-alias-label-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ne-chatActions { margin-left: auto; display: flex; gap: 2px; }
.ne-chatPane .ne-paneBody, .ne-paneBody { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.ne-transcript { flex: 1; min-height: 0; overflow-y: auto; padding: 14px 14px 18px; display: flex; flex-direction: column; gap: 12px; }
.ne-paneState { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 9px; color: var(--dsw-alias-label-secondary); text-align: center; padding: 24px; font-size: 12.5px; }
.ne-paneStateError { color: var(--dsw-alias-state-error-primary); }
.ne-paneEmpty { display: flex; flex-direction: column; align-items: center; gap: 10px; color: var(--dsw-alias-label-secondary); padding: 22px 12px; text-align: center; }
.ne-paneBanner {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin: 8px 14px 0; padding: 7px 10px; border-radius: 8px; font-size: 11.5px;
  color: var(--dsw-alias-state-warn-primary);
  background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 9%, transparent);
  border: 1px solid color-mix(in srgb, var(--dsw-alias-state-warn-primary) 28%, transparent);
}
.ne-msg { display: flex; flex-direction: column; gap: 4px; }
.ne-msgMeta { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.ne-msgWho { font-weight: 600; color: var(--dsw-alias-label-secondary); }
.ne-msgTime { margin-left: auto; font-variant-numeric: tabular-nums; }
.ne-aiBadge {
  display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px;
  border-radius: 6px; color: var(--dsw-alias-brand-primary);
  background: color-mix(in srgb, var(--dsw-alias-brand-primary) 12%, transparent);
}
.ne-bubble { padding: 9px 12px; border-radius: 12px; font-size: 12.5px; overflow-wrap: anywhere; line-height: 1.6; }
.ne-bubble > :last-child { margin-bottom: 0; }
.ne-bubbleUser { background: color-mix(in srgb, var(--dsw-alias-brand-primary) 10%, var(--dsw-alias-bg-layer-1)); border: 1px solid color-mix(in srgb, var(--dsw-alias-brand-primary) 18%, transparent); border-bottom-right-radius: 4px; align-self: flex-end; max-width: 88%; }
.ne-msgUser { align-items: flex-end; }
.ne-msgUser .ne-msgMeta { align-self: flex-end; }
.ne-bubbleAi { background: var(--dsw-alias-bg-layer-1); border: 1px solid var(--dsw-alias-border-l1); border-top-left-radius: 4px; box-shadow: 0 1px 3px color-mix(in srgb, var(--dsw-alias-label-primary) 4%, transparent); }
.ne-setupRow { border: 1px dashed var(--dsw-alias-border-l2); border-radius: 8px; padding: 7px 10px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.ne-setupSummary { cursor: pointer; display: flex; align-items: center; gap: 6px; list-style: none; }
.ne-setupText { margin: 8px 0 0; white-space: pre-wrap; }
.ne-rowError {
  display: flex; align-items: center; gap: 7px; padding: 7px 10px; border-radius: 8px; font-size: 11.5px;
  color: var(--dsw-alias-state-error-primary);
  background: color-mix(in srgb, var(--dsw-alias-state-error-primary) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--dsw-alias-state-error-primary) 25%, transparent);
}
.ne-rowNotice { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.ne-toolRow { border: 1px solid var(--dsw-alias-border-l1); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); padding: 6px 9px; font-size: 11.5px; }
.ne-toolRow[data-error="true"] { border-color: color-mix(in srgb, var(--dsw-alias-state-error-primary) 35%, transparent); }
.ne-toolSummary { display: flex; align-items: center; gap: 6px; cursor: pointer; list-style: none; color: var(--dsw-alias-label-secondary); }
.ne-toolName { color: var(--dsw-alias-brand-primary); font-size: 11px; }
.ne-toolState { color: var(--dsw-alias-state-error-primary); }
.ne-toolPre { margin: 7px 0 0; padding: 7px 9px; border-radius: 6px; overflow-x: auto; font-size: 11px; background: var(--dsw-alias-bg-layer-2); }
.ne-caret { display: inline-block; width: 2px; height: 12px; margin-left: 2px; vertical-align: -2px; background: var(--dsw-alias-brand-primary); animation: ne-blink 1s steps(2) infinite; }
@keyframes ne-blink { 50% { opacity: 0; } }
.ne-typing { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.ne-typingDots { display: inline-flex; gap: 3px; }
.ne-typingDots i { width: 4px; height: 4px; border-radius: 50%; background: currentColor; animation: ne-typing 1.2s ease-in-out infinite; }
.ne-typingDots i:nth-child(2) { animation-delay: 0.15s; }
.ne-typingDots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes ne-typing { 0%,60%,100% { opacity: 0.3; transform: translateY(0); } 30% { opacity: 1; transform: translateY(-2px); } }
.ne-composer { flex: none; padding: 10px 14px 11px; border-top: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--dsw-alias-bg-layer-1) 42%, transparent); }
.ne-composerRow { display: flex; align-items: flex-end; gap: 8px; }
.ne-composerInput {
  flex: 1; resize: none; min-height: 36px; max-height: 140px; padding: 8px 10px;
  border-radius: 10px; border: 1px solid var(--dsw-alias-border-l1);
  background: var(--dsw-alias-bg-layer-1); outline: none; font-size: 12.5px; line-height: 1.5;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}
.ne-composerInput:focus { border-color: color-mix(in srgb, var(--dsw-alias-brand-primary) 55%, var(--dsw-alias-border-l1)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-brand-primary) 10%, transparent); }
.ne-sendBtn {
  width: 34px; height: 34px; flex: none; border-radius: 9px; border: none; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--dsw-alias-brand-primary); color: var(--dsw-alias-bg-base);
}
.ne-sendBtn:disabled { opacity: 0.45; cursor: not-allowed; }
.ne-composerHint { margin: 6px 2px 0; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.ne-composerNotice { margin: 0 0 7px; font-size: 11.5px; color: var(--dsw-alias-state-error-primary); }

.ne-glyph { display: block; flex: none; }
.ne-loadingLine { display: flex; align-items: center; gap: 9px; padding: 22px; color: var(--dsw-alias-label-secondary); font-size: 12.5px; }
.ne-errorBox {
  margin: 18px 20px; padding: 12px 14px; border-radius: 10px; font-size: 12.5px;
  color: var(--dsw-alias-state-error-primary);
  background: color-mix(in srgb, var(--dsw-alias-state-error-primary) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--dsw-alias-state-error-primary) 25%, transparent);
  display: flex; flex-direction: column; gap: 8px; align-items: flex-start;
}

@media (max-width: 860px) {
  .ne-header { flex-wrap: wrap; min-height: 58px; padding: 9px 14px; }
  .ne-headerEnd { width: 100%; margin-left: 0; justify-content: flex-end; }
  .ne-subtitle { display: none; }
  .ne-tabs { padding: 0 10px; overflow-x: auto; }
  .ne-tab { padding: 8px 10px 9px; white-space: nowrap; }
}

@media (prefers-reduced-motion: reduce) {
  .ne-page *, .ne-page *::before, .ne-page *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`;
